package vn.hust.restaurant.service;import java.sql.*;import java.util.*;import vn.hust.restaurant.model.MenuItem;import vn.hust.restaurant.repository.MenuRepository;public class MenuService{private final MenuRepository r;public MenuService(MenuRepository r){this.r=r;}public List<MenuItem>list(String k,boolean a)throws SQLException{return r.findAll(k,a);}public Map<Integer,String>categories()throws SQLException{return r.categories();}public void save(MenuItem x)throws SQLException{if(x.name().isBlank()||x.price().signum()<0)throw new IllegalArgumentException("Tên món/đơn giá không hợp lệ");r.save(x);}public void toggle(int id,boolean a)throws SQLException{r.toggle(id,a);}}
